css:
.sl-article-statement {
    background-color: var(--smartlearn-bg);
    min-height: 60vh;
    padding-block: 5rem;
}
@media (min-width: 992px) {
    .sl-article-statement { padding-block: 8rem; }
}

.sl-article-statement .sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-article-statement .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-article-statement .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-article-statement .sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-article-statement .sl-border { border-color: var(--smartlearn-card-border) !important; }
.sl-article-statement .sl-tracking-wide { letter-spacing: 0.1em; }

.sl-article-statement .sl-animated-bg {
    pointer-events: none;
    background: radial-gradient(circle at 15% 50%, color-mix(in srgb, var(--smartlearn-primary) 15%, transparent), transparent 50%),
                radial-gradient(circle at 85% 30%, color-mix(in srgb, var(--smartlearn-primary) 10%, transparent), transparent 50%);
    animation: sl-article-statement-gradient 15s ease-in-out infinite alternate;
}

@keyframes sl-article-statement-gradient {
    0% { transform: scale(1) translate(0, 0); }
    50% { transform: scale(1.1) translate(2%, 2%); }
    100% { transform: scale(1) translate(-2%, -2%); }
}

@media (prefers-reduced-motion: reduce) {
    .sl-article-statement .sl-animated-bg { animation: none; }
}
